extends CanvasLayer

var peer = ENetMultiplayerPeer.new()
@export var player_scene: PackedScene
@export var network_layer: CanvasLayer
@export var ip_input: LineEdit

func _ready():
	# Когда кто-то подключается к нам (мы сервер)
	multiplayer.peer_connected.connect(add_player)
	# Когда кто-то отключается
	multiplayer.peer_disconnected.connect(remove_player)

func _on_host_btn_pressed():
	peer.create_server(7000)
	multiplayer.multiplayer_peer = peer
	add_player(1)
	network_layer.hide()

func _on_join_btn_pressed():
	var ip = ip_input.text
	peer.create_client(ip, 7000)
	multiplayer.multiplayer_peer = peer
	network_layer.hide()

func add_player(id):
	if not multiplayer.is_server():
		return
	var p = player_scene.instantiate()
	p.name = str(id) # Теперь у каждого игрока имя - это его уникальный номер
	p.position = Vector2(100, 50)
	get_parent().add_child(p)

func remove_player(id):
	var p = get_node_or_null(str(id))
	if p: p.queue_free()

